import type { Fixture } from './fixtures';

/**
 * The Depth Map sample project. Images are bundled in public/samples, so it
 * works offline. Their maps are always generated by the depth model on the
 * spot, never stored as pictures. Near and far boxes make it a regression test.
 */
export interface Sample {
  id: string; type: string; title: string; url: string; credit: string; license: string; source: string;
  near: number[]; far: number[];
}

export const SAMPLES: Sample[] = [
  { id: 'portrait', type: 'Portrait', title: 'Portrait', url: '/samples/portrait.jpg', credit: 'rawpixel.com', license: 'CC0', source: 'Wikimedia Commons', near: [0.42, 0.5, 0.62, 0.8], far: [0.04, 0.08, 0.26, 0.34] },
  { id: 'flower', type: 'Flower', title: 'Flower Close-up', url: '/samples/flower.jpg', credit: 'Jon Sullivan', license: 'Public domain', source: 'Wikimedia Commons', near: [0.38, 0.62, 0.6, 0.76], far: [0, 0, 0.08, 0.12] },
  { id: 'architecture', type: 'Architecture', title: 'Pergola Walkway', url: '/samples/architecture.jpg', credit: 'Laitche', license: 'Public domain', source: 'Wikimedia Commons', near: [0.3, 0.9, 0.7, 0.99], far: [0.44, 0.56, 0.47, 0.6] },
  { id: 'landscape', type: 'Landscape', title: 'Cradle Mountain', url: '/samples/landscape.jpg', credit: 'Dhx1', license: 'CC0', source: 'Wikimedia Commons', near: [0.08, 0.82, 0.3, 0.97], far: [0.62, 0.05, 0.9, 0.2] },
];

export const sampleFixture = (s: Sample): Fixture => ({ id: s.id, type: s.type, title: s.title, checks: 'Depth Map sample', source: `${s.credit}. ${s.license}`, url: s.url, near: s.near, far: s.far });

export async function loadSampleFile(id: string) {
  const s = SAMPLES.find((x) => x.id === id);
  if (!s) throw new Error('Unknown sample.');
  const r = await fetch(s.url);
  if (!r.ok) throw new Error(`The sample image could not be loaded (HTTP ${r.status}).`);
  return new File([await r.blob()], `${s.title}.jpg`, { type: 'image/jpeg' });
}
